export function ValueProposition({
  headline = "{{headline}}",
  supportingText = "{{supportingText}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  emphasise = {{emphasise}},
}) {
  const wrap = {
    centered: { textAlign: "center", marginInline: "auto" },
    "left-aligned": { textAlign: "left" },
    split: { display: "grid", gridTemplateColumns: "1fr 1fr", alignItems: "center", gap: 24, textAlign: "left", maxWidth: 640 },
  }[layout] ?? {};
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", maxWidth: 480, ...wrap }}>
      <h2 style={{
        margin: "0 0 12px",
        fontWeight: 700,
        lineHeight: 1.2,
        fontSize: emphasise ? 32 : 28,
        textDecoration: emphasise ? "underline" : "none",
        textDecorationColor: accent,
        textDecorationThickness: emphasise ? "4px" : undefined,
        textUnderlineOffset: emphasise ? "6px" : undefined,
      }}>
        {headline}
      </h2>
      <p style={{ margin: 0, fontSize: 16, lineHeight: 1.5, color: "#241430", opacity: 0.8 }}>{supportingText}</p>
    </div>
  );
}
